# Frozen copy of core.pages.LEGACY_MODULE_PAGES as it was when roles came in
# - what each old-style staff module meant, every page with write.
LEGACY_MODULE_PAGES = {
    "oms": ["oms.dashboard", "oms.orders", "oms.critical_orders", "reports", "batch", "tickets"],
    "ims": ["ims.inventory", "ims.purchase_orders", "reports", "tickets"],
    "wms": ["wms.packing", "wms.returns_desk", "reports", "batch", "tickets"],
    "finance": ["finance.home", "tickets"],
    "returns": ["wms.returns_desk", "wms.packing", "tickets"],
}
MODULE_NAMES = {"oms": "OMS", "ims": "IMS", "wms": "WMS", "finance": "Financify"}
MODULE_ORDER = ["oms", "ims", "wms", "finance"]


def _role_name(modules):
    if modules == ["returns"]:
        return "Returns Associate"
    ordered = [m for m in MODULE_ORDER if m in modules]
    return " + ".join(MODULE_NAMES[m] for m in ordered) + " Staff"


def staff_to_roles(apps, schema_editor):
    """Every existing staff login gets a role that gives exactly what its
    modules gave before - one role per store per combination of modules
    ("OMS Staff", "OMS + WMS Staff", "Returns Associate", ...)."""
    Membership = apps.get_model("core", "Membership")
    Role = apps.get_model("core", "Role")

    for membership in Membership.objects.filter(role="org_user", role_ref__isnull=True):
        modules = [m for m in (membership.allowed_modules or []) if m in LEGACY_MODULE_PAGES]
        if not modules:
            continue
        key = ["returns"] if "returns" in modules else sorted(set(modules), key=MODULE_ORDER.index)
        permissions = {}
        for module in key:
            for page in LEGACY_MODULE_PAGES[module]:
                permissions[page] = "write"
        role, _ = Role.objects.get_or_create(
            organization_id=membership.organization_id,
            name=_role_name(key),
            defaults={"permissions": permissions},
        )
        membership.role_ref = role
        membership.save(update_fields=["role_ref"])


